c.STDIO:
#include <stdio.h>

int main(void) {
    char digits[101];
    scanf("%100s", digits);
    int sum = 0;
    for (int i = 0; digits[i] != '\0'; i++) {
        int weight = i % 2 == 0 ? 1 : 3;
        sum += (digits[i] - '0') * weight;
    }
    printf("%d\n", (10 - sum % 10) % 10);
    return 0;
}

